// Récupère le tableau des URLs existantes depuis le nœud Aggregate
const existingUrls = $('Aggregate').first().json.url.map(u => u.trim());

// Filtre les nouveaux articles pour ne garder que ceux dont l'URL n'existe pas déjà
const newItems = $input.all().filter(item => {
  const cleanUrl = (item.json.url || '').trim();
  return !existingUrls.includes(cleanUrl);
});

return newItems;

